const char* pbr_vs=R"GLSL(#version 310 es
precision highp float;layout(location=0)in vec3 a_position;layout(location=1)in vec3 a_normal;layout(location=2)in vec2 a_uv;layout(std140,binding=0)uniform Camera{mat4 u_view_projection;};uniform mat4 u_model;out vec3 v_world_position;out vec3 v_normal;out vec2 v_uv;void main(){vec4 p=u_model*vec4(a_position,1.);v_world_position=p.xyz;v_normal=normalize(mat3(u_model)*a_normal);v_uv=a_uv;gl_Position=u_view_projection*p;}
)GLSL";
const char* pbr_fs=R"GLSL(#version 310 es
precision highp float;layout(location=0)out vec4 o_color;struct Light{vec4 position_type;vec4 direction_intensity;vec4 color_range;};layout(std140,binding=1)uniform Lights{Light u_lights[256];uint u_light_count;};layout(std140,binding=2)uniform Material{vec4 u_base_roughness;vec4 u_metal_specular;vec4 u_emission_opacity;};uniform vec3 u_camera_position;uniform float u_ambient_intensity;in vec3 v_world_position;in vec3 v_normal;in vec2 v_uv;const float PI=3.14159265359;float saturate(float x){return clamp(x,0.,1.);}vec3 fresnel(vec3 f0,float c){return f0+(1.-f0)*pow(1.-c,5.);}void main(){vec3 n=normalize(v_normal);vec3 v=normalize(u_camera_position-v_world_position);vec3 base=u_base_roughness.rgb;float rough=max(u_base_roughness.a,.045);float metallic=saturate(u_metal_specular.x);vec3 f0=mix(vec3(.04),base,metallic);vec3 lo=vec3(0);for(uint i=0u;i<u_light_count&&i<256u;++i){Light l=u_lights[i];vec3 L=l.position_type.w<.5?normalize(-l.direction_intensity.xyz):normalize(l.position_type.xyz-v_world_position);float dist=length(l.position_type.xyz-v_world_position);float att=l.position_type.w<.5?1.:saturate(1.-dist/max(l.color_range.w,.001));float ndl=saturate(dot(n,L));if(ndl<=0.)continue;vec3 h=normalize(v+L);float ndh=saturate(dot(n,h));float vdh=saturate(dot(v,h));float a=rough*rough,a2=a*a,den=ndh*ndh*(a2-1.)+1.;float D=a2/(PI*den*den),k=(rough+1.)*(rough+1.)/8.,nv=saturate(dot(n,v));float Gv=nv/(nv*(1.-k)+k),Gl=ndl/(ndl*(1.-k)+k);vec3 F=fresnel(f0,vdh);vec3 spec=(D*Gv*Gl*F)/max(4.*nv*ndl,.001);vec3 kd=(1.-F)*(1.-metallic);lo+=(kd*base/PI+spec)*l.color_range.rgb*l.direction_intensity.w*ndl*att;}vec3 color=lo+base*u_ambient_intensity+u_emission_opacity.rgb;color=color/(color+1.);color=pow(max(color,vec3(0)),vec3(1./2.2));o_color=vec4(color,saturate(u_emission_opacity.a));}
)GLSL";
const char* mobile_vs=R"GLSL(#version 310 es
precision highp float;layout(location=0)in vec3 a_position;layout(location=1)in vec3 a_normal;layout(location=2)in vec2 a_uv;uniform mat4 u_view_projection;uniform mat4 u_model;out vec3 v_normal;out vec3 v_world_position;out vec2 v_uv;void main(){vec4 p=u_model*vec4(a_position,1.);v_world_position=p.xyz;v_normal=normalize(mat3(u_model)*a_normal);v_uv=a_uv;gl_Position=u_view_projection*p;}
)GLSL";
const char* mobile_fs=R"GLSL(#version 310 es
precision highp float;layout(location=0)out vec4 o_color;layout(binding=7)uniform sampler2D u_shadow_map;layout(binding=8)uniform sampler2D u_environment_map;layout(binding=9)uniform sampler2D u_ibl_irradiance;uniform vec4 u_base_roughness;uniform vec4 u_metal_specular;uniform vec4 u_emission_opacity;uniform vec3 u_camera_position;uniform float u_ambient_intensity;uniform vec3 u_light_direction;uniform vec3 u_light_color;uniform float u_light_intensity;uniform mat4 u_shadow_vp[4];uniform vec4 u_shadow_splits;uniform int u_shadow_cascade_count;uniform float u_shadow_bias;uniform float u_ibl_intensity;in vec3 v_normal;in vec3 v_world_position;in vec2 v_uv;int cascade_index(float d){if(u_shadow_cascade_count<=1)return 0;if(d<=u_shadow_splits.x)return 0;if(d<=u_shadow_splits.y)return 1;if(d<=u_shadow_splits.z)return 2;return 3;}float shadow_one(vec3 p,int i){vec4 q=u_shadow_vp[i]*vec4(p,1.);if(abs(q.w)<1e-6)return 1.;q.xyz/=q.w;vec2 uv=q.xy*.5+.5;float z=q.z*.5+.5;if(uv.x<0.||uv.x>1.||uv.y<0.||uv.y>1.||z<0.||z>1.)return 1.;vec2 texel=1./vec2(textureSize(u_shadow_map,0));float s=0.;for(int y=-1;y<=1;y++)for(int x=-1;x<=1;x++){float d=texture(u_shadow_map,uv+vec2(x,y)*texel).r;s+=(z-u_shadow_bias)<=d?1.:0.;}return s/9.;}float shadow_factor(vec3 p){float d=length(u_camera_position-p);int i=cascade_index(d);float s=shadow_one(p,i);if(i<3){float split=i==0?u_shadow_splits.x:(i==1?u_shadow_splits.y:u_shadow_splits.z);float blend=smoothstep(split*.88,split,d);s=mix(s,shadow_one(p,i+1),blend);}return s;}vec2 env_uv(vec3 d){float phi=atan(d.z,d.x),theta=acos(clamp(d.y,-1.,1.));return vec2(phi/6.2831853+.5,theta/3.14159265);}vec3 env_lookup(vec3 d){return texture(u_environment_map,env_uv(d)).rgb;}void main(){vec3 n=normalize(v_normal),l=normalize(-u_light_direction),v=normalize(u_camera_position-v_world_position),h=normalize(l+v);float ndl=max(dot(n,l),0.);vec3 base=u_base_roughness.rgb;float rough=clamp(u_base_roughness.a,.045,1.);float metallic=clamp(u_metal_specular.x,0.,1.);vec3 f0=mix(vec3(.04),base,metallic);float spec=pow(max(dot(n,h),0.),mix(64.,4.,rough))*mix(.04,1.,metallic);float shadow=shadow_factor(v_world_position);vec3 irradiance=texture(u_ibl_irradiance,env_uv(n)).rgb;vec3 prefilter=textureLod(u_environment_map,env_uv(reflect(-v,n)),rough*6.).rgb;float ndv=max(dot(n,v),0.);vec3 ibl=(base*(1.-metallic)*irradiance+prefilter*mix(vec3(.04),f0,metallic))*(.2+.8*ndv)*u_ibl_intensity;vec3 color=base*(u_ambient_intensity+ndl*u_light_intensity*u_light_color*shadow)+f0*spec*shadow+ibl+u_emission_opacity.rgb;float fog=exp(-length(u_camera_position-v_world_position)*.0015);color=mix(env_lookup(normalize(v)),color,clamp(fog,0.,1.));color=color/(color+1.);color=pow(max(color,vec3(0)),vec3(1./2.2));o_color=vec4(color,clamp(u_emission_opacity.a,0.,1.));}
)GLSL";
const char* textured_fs=R"GLSL(#version 310 es
precision highp float;layout(location=0)out vec4 o_color;layout(binding=7)uniform sampler2D u_shadow_map;layout(binding=8)uniform sampler2D u_environment_map;layout(binding=9)uniform sampler2D u_ibl_irradiance;uniform vec4 u_base_roughness;uniform vec4 u_metal_specular;uniform vec4 u_emission_opacity;uniform vec3 u_camera_position;uniform float u_ambient_intensity;uniform vec3 u_light_direction;uniform vec3 u_light_color;uniform float u_light_intensity;uniform sampler2D u_base_texture;uniform sampler2D u_roughness_texture;uniform sampler2D u_metallic_texture;uniform sampler2D u_normal_texture;uniform sampler2D u_ao_texture;uniform sampler2D u_emission_texture;uniform sampler2D u_opacity_texture;uniform float u_use_textures;uniform mat4 u_shadow_vp[4];uniform vec4 u_shadow_splits;uniform int u_shadow_cascade_count;uniform float u_shadow_bias;uniform float u_ibl_intensity;in vec3 v_normal;in vec3 v_world_position;in vec2 v_uv;const float PI=3.14159265359;float sat(float x){return clamp(x,0.,1.);}vec3 F(vec3 f0,float c){return f0+(1.-f0)*pow(1.-c,5.);}mat3 tbn(vec3 n){vec3 dp1=dFdx(v_world_position),dp2=dFdy(v_world_position);vec2 duv1=dFdx(v_uv),duv2=dFdy(v_uv);float den=duv1.x*duv2.y-duv1.y*duv2.x;vec3 t;if(abs(den)>1e-5)t=normalize((dp1*duv2.y-dp2*duv1.y)/den);else{vec3 a=abs(n.y)<.9?vec3(0,1,0):vec3(1,0,0);t=normalize(cross(a,n));}vec3 b=normalize(cross(n,t));return mat3(t,b,n);}int cascade_index(float d){if(u_shadow_cascade_count<=1)return 0;if(d<=u_shadow_splits.x)return 0;if(d<=u_shadow_splits.y)return 1;if(d<=u_shadow_splits.z)return 2;return 3;}float shadow_one(vec3 p,int i){vec4 q=u_shadow_vp[i]*vec4(p,1.);if(abs(q.w)<1e-6)return 1.;q.xyz/=q.w;vec2 uv=q.xy*.5+.5;float z=q.z*.5+.5;if(uv.x<0.||uv.x>1.||uv.y<0.||uv.y>1.||z<0.||z>1.)return 1.;vec2 texel=1./vec2(textureSize(u_shadow_map,0));float s=0.;for(int y=-1;y<=1;y++)for(int x=-1;x<=1;x++){float d=texture(u_shadow_map,uv+vec2(x,y)*texel).r;s+=(z-u_shadow_bias)<=d?1.:0.;}return s/9.;}float shadow_factor(vec3 p){float d=length(u_camera_position-p);int i=cascade_index(d);float s=shadow_one(p,i);if(i<3){float split=i==0?u_shadow_splits.x:(i==1?u_shadow_splits.y:u_shadow_splits.z);float blend=smoothstep(split*.88,split,d);s=mix(s,shadow_one(p,i+1),blend);}return s;}vec2 env_uv(vec3 d){float phi=atan(d.z,d.x),theta=acos(clamp(d.y,-1.,1.));return vec2(phi/(2.*PI)+.5,theta/PI);}void main(){vec3 n=normalize(v_normal);vec4 base_sample=texture(u_base_texture,v_uv);float rough_tex=texture(u_roughness_texture,v_uv).r;float metal_tex=texture(u_metallic_texture,v_uv).r;float ao=texture(u_ao_texture,v_uv).r;vec3 normal_sample=texture(u_normal_texture,v_uv).xyz*2.-1.;vec3 emission_sample=texture(u_emission_texture,v_uv).rgb;float opacity_sample=texture(u_opacity_texture,v_uv).r;vec3 base=mix(u_base_roughness.rgb,base_sample.rgb,u_use_textures);float rough=mix(u_base_roughness.a,rough_tex,u_use_textures);float metallic=mix(u_metal_specular.x,metal_tex,u_use_textures);if(u_use_textures>.5)n=normalize(tbn(n)*normalize(normal_sample));vec3 v=normalize(u_camera_position-v_world_position),l=normalize(-u_light_direction),h=normalize(v+l);float ndl=sat(dot(n,l)),ndl2=max(ndl,.0001),nv=sat(dot(n,v)),ndh=sat(dot(n,h)),vdh=sat(dot(v,h));rough=max(rough,.045);float a=rough*rough,a2=a*a,den=ndh*ndh*(a2-1.)+1.;float D=a2/(PI*den*den),k=(rough+1.)*(rough+1.)/8.;float Gv=nv/(nv*(1.-k)+k),Gl=ndl2/(ndl2*(1.-k)+k);vec3 f0=mix(vec3(.04),base,clamp(metallic,0.,1.));vec3 spec=(D*Gv*Gl*F(f0,vdh))/max(4.*nv*ndl2,.001);vec3 kd=(1.-F(f0,vdh))*(1.-clamp(metallic,0.,1.));float shadow=shadow_factor(v_world_position);vec3 direct=(kd*base/PI+spec)*u_light_color*u_light_intensity*ndl*shadow;vec3 irradiance=texture(u_ibl_irradiance,env_uv(n)).rgb;vec3 prefilter=textureLod(u_environment_map,env_uv(reflect(-v,n)),rough*6.).rgb;vec3 ibl=(base*(1.-clamp(metallic,0.,1.))*irradiance+prefilter*f0)*(.2+.8*nv)*u_ibl_intensity*mix(1.,ao,u_use_textures);vec3 emission=mix(u_emission_opacity.rgb,emission_sample,u_use_textures);float alpha=mix(u_emission_opacity.a,opacity_sample,u_use_textures);vec3 color=(direct+base*u_ambient_intensity*mix(1.,ao,u_use_textures)+ibl+emission);float fog=exp(-length(u_camera_position-v_world_position)*.0015);color=mix(texture(u_environment_map,env_uv(normalize(v))).rgb,color,sat(fog));color=color/(color+1.);color=pow(max(color,vec3(0)),vec3(1./2.2));o_color=vec4(color,sat(alpha));}
)GLSL";
const char* skinned_vs=R"GLSL(#version 310 es
precision highp float;layout(location=0)in vec3 a_position;layout(location=1)in vec3 a_normal;layout(location=2)in vec2 a_uv;layout(location=3)in vec4 a_bone_ids;layout(location=4)in vec4 a_bone_weights;uniform mat4 u_view_projection;uniform mat4 u_model;uniform mat4 u_bones[128];uniform int u_bone_count;out vec3 v_normal;out vec3 v_world_position;out vec2 v_uv;void main(){vec4 local_p=vec4(a_position,1.);vec3 local_n=a_normal;mat4 skin=mat4(0.);float weight_sum=0.;for(int i=0;i<4;++i){float w=a_bone_weights[i];int id=int(a_bone_ids[i])-1;if(w>0.&&id>=0&&id<u_bone_count){skin+=u_bones[id]*w;weight_sum+=w;}}if(weight_sum<=0.)skin=mat4(1.);else if(weight_sum<1.)skin+=mat4(1.)*(1.-weight_sum);vec4 p=u_model*skin*local_p;v_world_position=p.xyz;v_normal=normalize(mat3(u_model*skin)*local_n);v_uv=a_uv;gl_Position=u_view_projection*p;}
)GLSL";
const char* unlit_vs=R"GLSL(#version 310 es
precision highp float;layout(location=0)in vec3 a_position;layout(location=2)in vec2 a_uv;layout(std140,binding=0)uniform Camera{mat4 u_view_projection;};uniform mat4 u_model;out vec2 v_uv;void main(){v_uv=a_uv;gl_Position=u_view_projection*u_model*vec4(a_position,1.);}
)GLSL"; const char* unlit_fs=R"GLSL(#version 310 es
precision highp float;layout(location=0)out vec4 o_color;uniform vec4 u_color;void main(){o_color=u_color;}
)GLSL";
